  ('davos-switzerland', '01F', 'Davos', 'Switzerland', 'Europe''s high-alpine all-rounder', 'live', 'verified', 'northernLights', 'Switzerland & the Alps', '{"ski","culture","wellness","hiking","ultra"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Highest town in the Alps at 1,560 m; former tuberculosis climate-cure resort (Thomas Mann''s Magic Mountain); population ~11,000-12,000","Davos Klosters Mountains: ~300 km slopes, 6 mountains (Parsenn, Jakobshorn, Madrisa, Rinerhorn, Schatzalp, Pischa), 57 transport systems","Parsenn: 95.5 km slopes, 810-2,844 m, 18 lifts; the 12 km Weissfluhgipfel-Kublis descent is one of Europe''s longest runs","Jakobshorn (freestyle): 41.2 km slopes, 1,535-2,568 m, Jatz Park; Klosters Gotschna cable car to 2,285 m + Madrisa to 2,602 m","Spengler Cup since 1923 (Dr Carl Spengler) — oldest club ice-hockey tournament in the world; 98th ed. 26-31 Dec 2026; HC Davos record 17 titles (2025)","World Economic Forum hosted every January since 1971 (2,500+ delegates); Davos leads the global mountain meeting market","Kirchner Museum (Gigon & Guyer, opened 1992, Daylight Award 2012) holds the world''s largest Ernst Ludwig Kirchner (1880-1938) collection","Cradle of ski tourism: world''s first T-bar drag-lift on the Bolgen 1934; home of the SLF national avalanche-research institute (since 1945); 8 toboggan runs; 700 km bike net + Alps Epic Trail Davos"],"safety":{"emergency":"112 / 117 police / 118 fire / 144 ambulance / 1414 REGA alpine air-rescue / 145 poison","hospital":"Spital Davos 24/7 emergency centre + rescue (emergency +41 81 414 88 88 / 144); trauma transfer Chur/Zurich, often by REGA","advisory_level":"L1","malaria":"none","yellow_fever":"not required","activity_note":"High-alpine winter sports: off-piste avalanche risk (SLF daily bulletin, 5-level scale; transceiver/shovel/probe + guide; the Wang/Gotschnagrat off-piste is lethal), altitude/AMS (town 1,560 m to Weissfluhgipfel 2,844 m), cold/whiteout; fast toboggan runs; rescue REGA 1414"},"timing":{"peak":"High winter — Spengler Cup week (26-31 Dec), Feb half-terms + WEF week (mid-Jan); town booked out at multiples","shoulder":"Early Dec (pre-Spengler) + late-season Mar-Apr skiing; Sep-early Oct larch-gold hiking/biking","green":"Zwischensaison May-Jun + Nov (many hotels/lifts closed; lowest rates)","booking_lead":"Spengler + New Year + WEF 4-9 mo (WEF removes town-wide inventory); regular winter 2-4 mo; summer 1-3 mo","off_season_specials":"Summer hiking + 700 km bike net (Jun-Sep); autumn larch-gold + wellness (Sep-Oct); spring-ski value (late Mar-Apr)","event_peaks":"Spengler Cup (26-31 Dec), WEF (mid-Jan), ski holidays (Dec-Apr), summer trail/bike events","campaign_start":"Next winter + Spengler hospitality by Jun-Aug; summer hiking/biking + spring-ski from Jan; autumn larch-gold + wellness from spring"},"jewels":[{"name":"The 12 km Weissfluhgipfel-Kublis descent","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"~CHF 86/day lift; instructor ~CHF 400-600/day (approx)","timing":"ski ~late Nov-mid Apr; verify","commission_path":"school/operator 10-15%","draw_rank":1,"hook":"one of the longest runs in Europe drops 12 km from the Weissfluhgipfel down to Küblis","si":"ski","blurb":"one of the longest runs in Europe drops 12 km from the Weissfluhgipfel down to Küblis","when":"ski ~late Nov-mid Apr; verify","commission":"school/operator 10-15%"},{"name":"Ski-safari the six mountains on one pass (~300 km)","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"~CHF 53-86/day pass; instructor ~CHF 400-600/day (approx)","timing":"High winter — Spengler Cup week , Feb half-terms + WEF week","commission_path":"school/operator 10-15%","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"link Parsenn, Jakobshorn, Madrisa, Rinerhorn, Pischa and Schatzalp across ~300 km on the Davos Klosters Mountains pass","si":"ski","blurb":"li